import{_ as r,a8 as s,o as l,c as e,ah as a,K as o}from"./chunks/framework.DfRfZwD_.js";import"./chunks/theme.DRBNExvt.js";const y=JSON.parse('{"title":"客服聊天记录 · 会话级知识提炼（店小蜜 KB）","description":"","frontmatter":{},"headers":[],"relativePath":"vault/_Skills/kb-chatlog-extract/SKILL.md","filePath":"vault/_Skills/kb-chatlog-extract/SKILL.md","lastUpdated":1788766183000}'),d={name:"vault/_Skills/kb-chatlog-extract/SKILL.md"};function g(h,t,c,p,k,u){const i=s("NolebaseGitContributors"),n=s("NolebaseGitChangelog");return l(),e("div",null,[t[0]||(t[0]=a(`<h1 id="客服聊天记录-·-会话级知识提炼-店小蜜-kb" tabindex="-1">客服聊天记录 · 会话级知识提炼（店小蜜 KB） <a class="header-anchor" href="#客服聊天记录-·-会话级知识提炼-店小蜜-kb" aria-label="Permalink to “客服聊天记录 · 会话级知识提炼（店小蜜 KB）”">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>把一个会话（客服聊天记录）里<strong>能进知识库的内容</strong>，用 LLM 理解<strong>抽取</strong>成「提炼前 / 提炼后」对照 CSV。<strong>抽取优先、原话优先</strong>：从多条聊天消息中抽取可复用问答并拼接成通顺文字，<strong>若客服原话已合理通顺则尽量不改写，避免内容丢失</strong>。逐批进行（默认每批 5 个会话），源数据只读不改、不清洗、不删。</p><p>本 skill 封装三件事：<strong>① 可靠读源</strong> ② <strong>选批 + 导出原始对话</strong> ③ <strong>安全的 CSV 写出并防损坏</strong>。 <strong>真正的提炼判断由 LLM 在对话中完成</strong>（见下方「提炼规则」）——脚本只做机械搬运与选批，<strong>不替你做判断</strong>。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to “何时使用”">​</a></h2><ul><li>用户有 <code>客服聊天记录.xlsx</code> 或导出的 <code>8.3~.csv</code>，要&quot;把能进知识库的聊天内容提炼出来&quot;。</li><li>用户说&quot;提炼下一批 / 批次N&quot;&quot;从这堆聊天记录里提知识库条目&quot;。</li><li>强调：<strong>LLM 理解提炼，不是脚本规则</strong>。脚本碰不到判断。</li><li>⚠️ <strong>范围边界（重要）</strong>：本 skill <strong>完全自包含</strong>，运行时<strong>只使用本目录 <code>scripts/</code> 下的三个脚本</strong>，禁止加载、引用或调用 <code>kb-extract</code>（及其 <code>redline.py</code> / <code>extract_runner.py</code> / <code>硬规则库.md</code>）。<code>kb-extract</code> 是文件级多 Agent RAG 方向（已对客服降级），与本会话级提炼任务<strong>无关，不得触发</strong>。</li></ul><h2 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to “输入”">​</a></h2><ul><li>聊天记录 CSV：<code>.../店小蜜/客服聊天记录_csv/8.3~.csv</code>（列：会话ID / 日期 / 时间 / 对象 / 发话者 / 消息 / 消息状态 / 商品ID / 商品；UTF-8 BOM）</li><li>或原始 xlsx：<code>.../店小蜜/客服聊天记录.xlsx</code>（含 sheet <code>8.3~</code>）</li><li><strong>商品目录（绑定权威源）</strong>：<code>.../店小蜜/商品ID.xlsx</code>（40 个商品ID / 36 个商品名，同一名对应多型号ID）； 已预处理为 <code>.../店小蜜/客服聊天记录_csv/商品ID_映射.json</code>（<code>id2name</code> / <code>name2ids</code>），<strong>「商品」列取值必须来自此处</strong>。</li><li>输出目录：<code>.../店小蜜/客服聊天记录_csv/</code>（批次 CSV 与原始对话子集 CSV 都放这）</li></ul><h2 id="核心流程-每批" tabindex="-1">核心流程（每批） <a class="header-anchor" href="#核心流程-每批" aria-label="Permalink to “核心流程（每批）”">​</a></h2><ol><li><strong>可靠读源</strong>：若只有 xlsx，先 <code>scripts/extract_sheet.py &lt;xlsx&gt; [sheet] [out_dir]</code> 导出 <code>8.3~.csv</code>。 ⚠️ 用 openpyxl <strong>普通 <code>load_workbook</code>（非 <code>read_only</code>）</strong>——<code>read_only</code> 对此文件会误读成 1 行。</li><li><strong>选批</strong>：<code>scripts/select_next_batch.py &lt;8.3~.csv&gt; &lt;输出目录&gt; [--count 5]</code>。 脚本自动跳过已做会话（扫描输出目录里 <code>知识提炼_批次*.csv</code> 收集 done 会话ID），挑 5 个： <strong>3 个带商品（尽量不同产品）+ 2 个无商品</strong>，且都有实质问答。把选中会话的<strong>全部原始消息</strong>写到 <code>输出目录/批次N_原始对话.csv</code>（保留完整 9 列、不截断、不重排）供 LLM 用 Read 工具直接阅读，并打印摘要。</li><li><strong>LLM 提炼</strong>：用 Read 工具读 <code>批次N_原始对话.csv</code>，按下方「提炼规则」逐会话理解，产出候选条目（每行 12 列）。</li><li><strong>安全写出</strong>：把候选条目写成 JSON（用 Write 工具，结构见下），再 <code>scripts/write_batch.py &lt;rows.json&gt;</code> 写出 <code>知识提炼_批次N.csv</code>（utf-8-sig），并<strong>自动校验文件头非 PK（防 zip 损坏）</strong>，损坏则自动从 zip 恢复重写。</li></ol><p>JSON 结构：</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#E06C75;">&quot;batch&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#D19A66;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#E06C75;">&quot;out&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;">&quot;可选覆盖路径&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#E06C75;"> &quot;rows&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">: [ {</span><span style="--shiki-light:#005CC5;--shiki-dark:#E06C75;">&quot;批次&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;">&quot;4&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#E06C75;">&quot;会话ID&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#E06C75;">&quot;商品&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#E06C75;">&quot;提炼前_原始问答&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;">&quot;客户:... → 客服:...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#E06C75;">            &quot;提炼后_问题&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#E06C75;">&quot;提炼后_答案&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#E06C75;">&quot;意图&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#E06C75;">&quot;答案标签&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#E06C75;">            &quot;适用对象&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#E06C75;">&quot;优先级&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#E06C75;">&quot;入库结论&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;">&quot;入库&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#E06C75;">&quot;备注&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;">}, </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FFFFFF;--shiki-dark-font-style:inherit;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#ABB2BF;"> ]}</span></span></code></pre></div><h2 id="列结构-12-列-固定顺序" tabindex="-1">列结构（12 列，固定顺序） <a class="header-anchor" href="#列结构-12-列-固定顺序" aria-label="Permalink to “列结构（12 列，固定顺序）”">​</a></h2><p><code>批次, 会话ID, 商品, 提炼前_原始问答, 提炼后_问题, 提炼后_答案, 意图, 答案标签, 适用对象, 优先级, 入库结论, 备注</code></p><ul><li><p><strong>批次</strong>：数字（1,2,3…）</p></li><li><p><strong>会话ID</strong>：原始会话ID</p></li><li><p><strong>商品</strong>：精确产品绑定（见规则 A）。<strong>必须以官方目录 <code>商品ID.xlsx</code>（已导出 <code>商品ID_映射.json</code>）中的「商品名」为准</strong>， 绝不得编造目录外的名字（如&quot;护腰椅&quot;&quot;沙发椅&quot;&quot;智能床&quot;&quot;换鞋凳&quot;这类营销泛指词）。源 商品 列有值直接用； 为空则从对话文本反推到<strong>目录内最贴近的商品名</strong>，备注&quot;由会话内容推断(源商品列空)&quot;。店级政策填 <code>通用</code>。 真判断不了（目录内无任何可贴商品）填 <code>⚠️ 复核</code>。</p></li><li><p><strong>提炼前_原始问答</strong>：<strong>审计与回查锚点</strong>。以<strong>抽取拼接</strong>为主：从该条 Q&amp;A 涉及的多条原始消息中<strong>抽取有用内容并拼接成通顺文字</strong>；若客服原话本身已合理通顺，则<strong>尽量逐字照录、不做改写</strong>。格式 <code>客户:&lt;原话&gt; → 客服:&lt;原话&gt;</code>。</p><ul><li>只允许：剔除套话/占位/空值行；多条相关消息拼接时用&quot;→&quot;衔接（如 <code>客户:安装容易不 → 客服:咱们是半安装 → 客服:收货后拧紧靠背四颗螺丝即可</code>）。</li><li><strong>禁止</strong>：删减客服回复中的关键信息（政策结论、具体数值、步骤）；凭空补全客服没说的话；把单条已通顺的回复改写成另一种说法。</li><li>若原始答复落在占位行（&quot;请在客户端查看原始聊天记录&quot;），<strong>照录占位原文</strong>，入库结论标 <code>⚠️复核</code>、备注说明内容丢失——<strong>不要替客服&quot;还原&quot;</strong>。</li></ul></li><li><p><strong>提炼后_问题</strong>：<strong>尽量还原用户原话</strong>——若客户提问本身通顺，则照录、不改写；仅当问题由多条消息组成时才拼接使其通顺。可去掉型号（云朵椅/Y1/pro/蒂芙尼…）和口语杂词，但<strong>保留语义完整</strong>。例：&quot;要自己安装吗？怎么安装？&quot;&quot;需要插座对吧？&quot;</p></li><li><p><strong>提炼后_答案</strong>：<strong>抽取并拼接、尽量少改写</strong>——从客服的多条回复消息中抽取该问题的答复内容拼接成通顺答案；<strong>若客服原回复本身已合理通顺，则尽量原样保留、不做精简</strong>，避免内容丢失（政策结论、数值、步骤等关键信息必须完整保留）。</p><ul><li>仅当多条消息拼接后衔接不畅时，做<strong>最小幅度的衔接性改写</strong>（加连接词、合并碎片句），<strong>不得删减关键信息</strong>。</li><li><strong>绝不自行补充客服原话未提及的退货/运费/质保/优惠等政策结论</strong>。客户问 A 客服答 A，答案只讲 A。</li></ul></li><li><p><strong>意图（必填 · 问题主题轴 · 开放分类）</strong>：顾客<strong>问了什么</strong>——<strong>开放定类，不预设固定枚举</strong>。以问题实际内容为准，遇到新类型就新增类别，<strong>不要为了套进旧类而强行合并不同主题</strong>。</p><ul><li>初始可参考的常见类别（非封闭、可增删）：价格优惠 / 功能卖点 / 售后退换 / 安装使用 / 物流配送 / 规格尺寸 / 订单支付 / 库存有货 / 材质工艺 / 其他 —— 仅作起步参考，实际问题超出时自由定类（如「老人适配/适老需求」「发票税务」「定制改款」等新类）。</li><li>分类粒度保持一致、互斥：同一会话同一子话题归一类，不要把多个不相关问题塞进一个意图。</li><li>来源：店小蜜测试集 10 意图作为<strong>初始参考</strong>，非强制全集。<strong>只看问题、不看答案</strong>。</li></ul></li><li><p><strong>答案标签（必填 · 答案内容轴）</strong>：这条<strong>答案属于什么内容类型</strong>——15 类：产品说明 / 尺寸规格 / 清洁保养 / 结构工艺 / 材质面料 / 需求识别 / 使用场景 / 安装指导 / 品牌介绍 / 价格议价 / 发货物流 / 质保售后 / 发票赠品 / 关怀祝福 / 越界拒答。 来源：店小蜜「知识管理-策略配置.xlsx」<strong>原生答案标签字段（入库必填，平台原生）</strong>。<strong>只看答案内容、不看问题</strong>。</p><p>⚠️ <strong>两轴正交（问 vs 答），允许且经常应当不同</strong>；下面 6 对是&quot;同概念在两轴的近义写法&quot;（<strong>意图开放定类后，这些只是常见示例，意图可超出此表自由命名</strong>），按各自轴分别填、<strong>不要强行统一</strong>：</p><table tabindex="0"><thead><tr><th>意图（问题轴 · 开放）</th><th>答案标签（答案轴 · 固定15类）</th><th>同一条目示例</th></tr></thead><tbody><tr><td>价格优惠</td><td>价格议价</td><td>问&quot;能优惠吗&quot; → 答案讲议价/活动</td></tr><tr><td>物流配送</td><td>发货物流</td><td>问&quot;什么时候发&quot; → 答案讲发货</td></tr><tr><td>规格尺寸</td><td>尺寸规格</td><td>问&quot;多大&quot; → 答案讲尺寸</td></tr><tr><td>安装使用</td><td>安装指导</td><td>问&quot;怎么装&quot; → 答案讲安装步骤</td></tr><tr><td>售后退换</td><td>质保售后</td><td>问&quot;能退吗&quot; → 答案讲质保/退换</td></tr><tr><td>材质工艺</td><td>材质面料</td><td>问&quot;什么材质&quot; → 答案讲面料/工艺</td></tr></tbody></table><ul><li>非近义对的正常跨轴（<strong>看起来不同是正确的</strong>）：问&quot;适合老人吗&quot;(意图=功能卖点) → 答案讲需求匹配(答案标签=需求识别)；问&quot;官方旗舰店吗&quot;(意图=品牌/渠道咨询) → 答案讲品牌(答案标签=品牌介绍)；问&quot;能给老人定制吗&quot;(意图=定制改款，开放新类) → 答案讲定制流程(答案标签=其他)。</li></ul></li><li><p><strong>适用对象</strong>：老人本人 / 子女代问 / 内部客服（可并排如&quot;子女代问/老人本人&quot;）</p></li><li><p><strong>优先级</strong>：P0 / P1 / P2（P0=核心售后物流政策；P1=常用；P2=补充）</p></li><li><p><strong>入库结论</strong>：<code>入库</code> / <code>⚠️ 复核</code> / <code>不入库</code></p></li><li><p><strong>备注</strong>：绑定依据 / 冲突提示 / 剔除原因等</p></li></ul><h2 id="提炼规则-llm-判断-逐步套用" tabindex="-1">提炼规则（LLM 判断，逐步套用） <a class="header-anchor" href="#提炼规则-llm-判断-逐步套用" aria-label="Permalink to “提炼规则（LLM 判断，逐步套用）”">​</a></h2><p><strong>A. 商品精确绑定（走「商品」列，不进问题/答案文本）—— 以官方目录为唯一权威</strong></p><ul><li><strong>权威源</strong>：店小蜜目录 <code>商品ID.xlsx</code>（位于 <code>.../店小蜜/</code>），已预处理为 <code>商品ID_映射.json</code> （<code>id2name</code>：商品ID→商品名；<code>name2ids</code>：商品名→多个ID）。<strong>所有「商品」取值必须是该目录里的商品名</strong>。</li><li><strong>源 商品 列有值</strong> → 该值即目录商品名，直接用；若源值带具体商品ID，把 ID 记到 <code>备注</code>（如&quot;商品ID:716876591029&quot;）。</li><li><strong>源 商品 列空</strong> → 扫对话文本是否点名具体商品，映射到<strong>目录内最贴近的商品名</strong>： <ul><li>客户说&quot;云朵椅/Y1/常乐椅/如意椅/云朵沙发/助起沙发/头枕/护颈枕/洗澡椅/护理床/减压床/起身助力器/ 床边扶手/拐杖/助行器/护腰垫/凝胶枕/三人沙发…&quot; → 取其目录名绑定，备注&quot;由会话内容推断(源商品列空)&quot;。</li><li>客户只说营销泛指词（&quot;护腰椅&quot;&quot;沙发椅&quot;&quot;椅子&quot;&quot;智能床&quot;）→ <strong>不要照抄这些词</strong>，要据上下文推断到具体目录商品 （如&quot;护腰椅&quot;应落为 云朵椅 / Y1 / 常乐椅 / 如意椅 / YI多功能椅 之一）；推断不出则绑最接近目录椅类 + 备注&quot;推断&quot;， 仍无法确定填 <code>⚠️ 复核</code>。</li><li>客户聊的根本不在目录内（如&quot;换鞋凳&quot;）→ 不能硬绑，标 <code>⚠️ 复核</code> 并在备注说明&quot;目录无此商品&quot;。</li></ul></li><li><strong>多型号聚合（重点）</strong>：目录里<strong>同一商品名对应多个型号ID</strong>（云朵椅=5个ID、Y1=2个、助起沙发=2个、洗澡椅=2个、 护颈枕/凝胶枕各2个、床边扶手=2个…）；反之个别 ID 聚合了多个类目（如 690137447012 含起身助力器/床边扶手/马桶扶手）。 <strong>绑定只写到「商品名」粒度，不新建型号名</strong>；具体型号差异（矮款/常规款/加长款…）留在问题/备注。</li><li><strong>变体锚定（矮款 / 常规款 / 加长款 / 高款 / 加大款…）</strong>：会话中只说变体词、未点具体商品时， 回溯该消息<strong>之前最近一次客户发送的商品链接（含商品ID）</strong>，变体即该商品的<strong>具体型号（同商品不同型号）</strong>； 商品列填该商品（目录名），&quot;矮款/常规款&quot;作为型号差异保留在问题或备注。若前面从未出现商品ID → <code>⚠️ 复核</code>（不是 <code>通用</code>）。</li><li><strong>属性 vs 政策二分</strong>：产品属性（安装方式 / 尺寸 / 材质 / 是否拆洗 / 颜色款式 / 承重 / 适用场景） → 绑推断商品；店级政策（发货时效 / 发货地 / 品牌控价不议价 / 运费险 / 七天无理由框架 / 上门取件平台设置） → 填 <code>通用</code>。</li><li>内容未点名且问题具体 → <code>⚠️ 复核</code>（不是 <code>通用</code>）。</li></ul><p><strong>B. 抽取拼接优先；原话合理则不改写</strong></p><ul><li>定位：从多条聊天消息中<strong>抽取</strong>该条问答的有用内容，<strong>拼接</strong>成通顺文字；<strong>优先保留客服原话，避免内容丢失</strong>。</li><li>例：客户问&quot;云朵椅自己安装吗&quot;，客服答&quot;咱们是半安装，收货后只需要拧紧靠背的四颗螺丝就可以的~并且我们都是有附带安装工具的，非常简单与便捷，一个人独立操作也没问题的&quot; → 提炼后_问题&quot;要自己安装吗？怎么安装？&quot;；提炼后_答案<strong>基本照录原话</strong>（仅去掉&quot;咱们/亲亲~&quot;等口语衬词，保留全部关键信息：半安装、四颗螺丝、附带工具、一人可操作）。</li><li>⚠️ <strong>忠实性硬约束（不变）</strong>：答案不得包含客服原话未提及的退货/运费/质保/优惠结论。曾发生把&quot;颜色不符&quot;答案 擅自加&quot;如不满意可走七天无理由&quot;的编造——已禁。</li><li>⚠️ <strong>内容保留优先（新增）</strong>：抽取拼接时，客服回复里的<strong>具体数值 / 政策结论 / 步骤顺序 / 材质名称</strong>等关键信息必须完整保留，不得因&quot;精简&quot;而丢失。若一条回复已通顺完整，则<strong>不做改写</strong>。</li><li><strong>意图 vs 答案标签（两轴正交）</strong>：意图按&quot;顾客问什么&quot;<strong>开放定类</strong>（见列结构）、答案标签按&quot;答案属什么内容&quot;填且<strong>固定为平台原生 15 类</strong>（入库必填），二者<strong>允许且经常应当不同</strong>； 近义对（价格优惠/价格议价 等 6 对，见「列结构」映射表，仅示例非封闭）按各自轴分别填，<strong>不要因看起来该一样而强行统一</strong>。</li></ul><p><strong>C. 入库判定</strong></p><ul><li><code>入库</code>：真实、可复用、合规、适用产品明确或通用。</li><li><code>⚠️ 复核</code>：① 关键答复落在占位行（&quot;请在客户端查看原始聊天记录&quot;）→ 内容丢失，判复核非入库； ② 适用产品不明确（且无法用变体锚定规则定位）；③ <strong>同一会话内</strong>客服口径自相矛盾（如先说可退后说不可退） → 标复核并备注矛盾，不私自合并。 ⚠️ <strong>跨会话 / 跨批次的一致性冲突（如&quot;是否上门安装&quot;不同会话相反）暂不做主动排查</strong>——会话量大、难判断真伪， 留待人工或后续统一口径阶段；仅当本批次内明显撞见时可在备注提一句，不阻断入库判定。</li><li><code>不入库</code>：① 客服&quot;晒图返现 / 返赠&quot;话术（违反对客铁律 #18 禁好评返现，整条剔除）； ② 动态库存（&quot;灰色缺货&quot;类，固化会过时误导）；③ 纯套话 / 纯占位 / 纯问候（无实质问答）； ④ <strong>价格优惠 / 价格议价整类不入库</strong>（问题主题为价格优惠/议价/能便宜吗/活动立减等价格相关，或 答案标签=<code>价格议价</code>）：价格相关答复由 AI 自动回答<strong>不可控</strong>， 一律不进知识库——含活动立减、多件折扣、&quot;品牌控价不议价&quot;等议价答复。价格问题建议走店小蜜<strong>转人工</strong>策略由人工处理，不进 KB。</li></ul><p><strong>D. 合规（强制卡点，非可选）</strong></p><ul><li>#18 禁返现：含返现 / 返赠诱导的整条剔除（结论=不入库）。</li><li>#16 禁内部词：含内部系统名 / 岗位流转 / 成本 / 供应商的过程描述，改写为对客表述。</li><li><strong>疾病宣称硬闸</strong>：家具 / 枕头 / 按摩类<strong>不得宣称治疗疾病</strong>（治疗 / 治愈 / 根治 / 理疗 / 颈椎病 / 腰椎 / 腰疼 / 腰痛 / 失眠 / 关节炎等），只能舒缓 / 辅助表述。 → <strong>写出后强制跑 <code>scripts/compliance_scan.py &lt;批次.csv&gt;</code></strong>，对命中的行必须改写去掉疾病宣称后才可 <code>入库</code>； 该脚本只做关键词标记，是否真违规由你判断并改写。</li></ul><h2 id="提炼规则-续-完整性优先" tabindex="-1">提炼规则（续）：完整性优先 <a class="header-anchor" href="#提炼规则-续-完整性优先" aria-label="Permalink to “提炼规则（续）：完整性优先”">​</a></h2><p><strong>E. 完整性优先（避免遗漏）</strong></p><ul><li>目标：<strong>尽量不漏</strong>。凡会话中出现的、可能可复用的真实问答都提炼，不按类型预筛、不列&quot;高优类型&quot;。</li><li>拿不准 → 偏向 <code>入库</code> 或 <code>⚠️ 复核</code>，<strong>不轻易 <code>不入库</code></strong>；<code>不入库</code> 仅留给明确违规 （返现/返赠 #18、动态库存、纯套话占位）。</li><li>同一会话可拆多条（不同子话题各一条），宁多勿漏。</li></ul><p><strong>F. 提炼前_原始问答 = 抽取拼接 + 原话优先</strong></p><ul><li>该列是<strong>审计与回查锚点</strong>，用于对照溯源。</li><li><strong>原话优先</strong>：若该条 Q&amp;A 的原始问答已通顺完整，则<strong>逐字照录</strong>，LLM 不得改写、概括、润色。</li><li><strong>允许的拼接</strong>：当一条问答分散在<strong>多条消息</strong>时，从这些消息中<strong>抽取有用内容，用&quot;→&quot;拼接</strong>成连贯文字，剔除套话/占位/空值行。拼接时不改动抽出的字词本身。</li><li><strong>禁止</strong>：删减关键信息（数值/政策/步骤）；补全缺失内容；把单条已通顺的回复改写成另一种说法。</li><li>若原始答复落在占位行（&quot;请在客户端查看原始聊天记录&quot;），该列<strong>照录占位原文</strong>，同时在 入库结论 标 <code>⚠️复核</code>、备注说明内容丢失——<strong>不要替客服&quot;还原&quot;出一段话</strong>。</li></ul><h2 id="推荐工作流-双-agent-并行提炼-main-合并-提升召回、减少遗漏" tabindex="-1">推荐工作流：双 agent 并行提炼 + main 合并（提升召回、减少遗漏） <a class="header-anchor" href="#推荐工作流-双-agent-并行提炼-main-合并-提升召回、减少遗漏" aria-label="Permalink to “推荐工作流：双 agent 并行提炼 + main 合并（提升召回、减少遗漏）”">​</a></h2><p>目标：两个独立 agent 各跑一遍提炼（最大化覆盖、互相补漏），main 只做合并整理、<strong>不做提炼</strong>。</p><ol><li><strong>派发两个提炼 agent（互不参考）</strong>：各加载本 skill，读同一 <code>批次N_原始对话.csv</code>，独立产出 <code>知识提炼_批次N_agentA.csv</code> / <code>知识提炼_批次N_agentB.csv</code>（用 write_batch.py，JSON 里 <code>out</code> 指定各自路径）。 两者都只待在 kb-chatlog-extract 内，互不读取对方结果。</li><li><strong>main 合并</strong>：读取两份 CSV，按 (会话ID, 提炼后_问题) 去重/合并，对答案不一致的做裁定 （取更忠实/更完整者），产出 consolidated <code>知识提炼_批次N.csv</code>（12 列，用 write_batch.py）。 <ul><li><strong>绑定裁定</strong>：两 agent 常在「商品」绑定上分歧（尤其源商品列空时）。裁定以<strong>对话文本最贴合</strong>的为准—— 如客户明确说「沙发椅」则绑 <code>沙发椅</code>，不取另一 agent 的 <code>护腰椅(推断)</code>；答案冲突取更忠实且<strong>去型号</strong>者。</li><li><strong>去重</strong>：用 <code>merge_two.py</code> 预合并后，务必对同会话近义问法（如 <code>椅套也想要</code> vs <code>椅子套也想要</code>、 <code>两扶手内径(坐宽)多长</code> vs <code>两扶手内径多长</code>）做归一化去重，保留信息更完整的一条，避免重复行。</li><li>可用 <code>scripts/merge_two.py &lt;A.csv&gt; &lt;B.csv&gt; &lt;out.csv&gt;</code> 预合并（自动去重 + 列出冲突待裁项），main 再据此定稿。</li></ul></li><li><strong>合规卡点</strong>：合并后跑 <code>scripts/compliance_scan.py &lt;知识提炼_批次N.csv&gt;</code>，修正疾病宣称命中行。</li><li><strong>范围</strong>：main 与两个 agent 均只使用本 skill 的 scripts，禁止触达 kb-extract。</li></ol><h2 id="已知坑-必读" tabindex="-1">已知坑（必读） <a class="header-anchor" href="#已知坑-必读" aria-label="Permalink to “已知坑（必读）”">​</a></h2><ul><li><strong>CSV 写出后被外部机制转成 zip（PK 头）</strong>：批次 2、批次 3 都中过。症状：后续读报 utf-8 解码失败、 文件头字节为 <code>PK</code>。<code>write_batch.py</code> 已内置校验 + 从 zip 恢复（openpyxl 读 sheet1，<code>read_only=False</code> 拿全 12 列，重写 utf-8-sig）。<strong>每次写后必验证</strong>。</li><li><strong>openpyxl <code>read_only</code> 误读行数</strong>：源 xlsx 必须用普通 <code>load_workbook</code>。</li></ul><h2 id="输出示例-一条入库-一条不入库" tabindex="-1">输出示例（一条入库 + 一条不入库） <a class="header-anchor" href="#输出示例-一条入库-一条不入库" aria-label="Permalink to “输出示例（一条入库 + 一条不入库）”">​</a></h2><table tabindex="0"><thead><tr><th>会话ID</th><th>商品</th><th>提炼前</th><th>提炼后_问题</th><th>提炼后_答案</th><th>意图</th><th>标签</th><th>结论</th></tr></thead><tbody><tr><td>丽萍1986816</td><td>护腰椅</td><td>客户:怎样清洗 → 客服:不做拆洗内部实木框架一体定型棉</td><td>怎样清洗？</td><td>不做可拆洗设计，内部实木框架+一体定型棉固定护腰弧度，拆开难复原贴合度；表面可用湿布擦拭清洁。</td><td>功能卖点</td><td>清洁保养</td><td>入库</td></tr><tr><td>老哥水云间</td><td>通用</td><td>客服:晒图反88话术</td><td>(违规话术)晒图返现</td><td></td><td>价格优惠</td><td>价格议价</td><td>不入库</td></tr></tbody></table><h2 id="与-kb-extract-的关系-仅背景-运行时禁止加载" tabindex="-1">与 kb-extract 的关系（仅背景，运行时禁止加载） <a class="header-anchor" href="#与-kb-extract-的关系-仅背景-运行时禁止加载" aria-label="Permalink to “与 kb-extract 的关系（仅背景，运行时禁止加载）”">​</a></h2><p><code>kb-extract</code>（多 Agent RAG 方向，已降级）覆盖文件级（md/xlsx/pdf/图/视频）解析与合规基建；本 skill 是其 <strong>会话级聊天记录</strong>特化分支：输入是&quot;会话&quot;，输出是&quot;提炼前/提炼后对照 CSV&quot;，提炼判断由 LLM 做。 合规精神（#18 / #16 / 忠实）一致，仅作背景参照——<strong>本 skill 运行时不加载、不调用 <code>kb-extract</code>，所有规则以本文件为准</strong>。</p>`,38)),o(i),o(n)])}const _=r(d,[["render",g]]);export{y as __pageData,_ as default};
